// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from pieUpdate ----
interface PieUpdateRow {
  apples: number;
  oranges: number;
}

const pieUpdateData: PieUpdateRow[] = [
  { apples: 53245, oranges: 200 },
  { apples: 28479, oranges: 200 },
  { apples: 19697, oranges: 200 },
  { apples: 24037, oranges: 200 },
  { apples: 40245, oranges: 200 },
];

const DURATION = 750;
const INTERVAL = 2000;
const KEYS: (keyof PieUpdateRow)[] = ['apples', 'oranges'];

type ArcDatum = d3.PieArcDatum<PieUpdateRow>;
type TweenedPath = SVGPathElement & { _current?: ArcDatum };

/** One row per slice carrying a value for each series, plus the series to cycle through. */
export type Data = {
  rows: { apples: number; oranges: number }[];
  keys: ('apples' | 'oranges')[];
};

const DEMO: Data = { rows: pieUpdateData, keys: KEYS };

export default function PieChartUpdate({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const ref = useRef<SVGSVGElement>(null);
  const height = Math.min(500, width / 2);

  useEffect(() => {
    if (!ref.current || width === 0) return;

    const svg = d3.select(ref.current);
    svg.selectAll('*').remove(); // StrictMode runs this effect twice

    const outerRadius = height / 2 - 10;
    const innerRadius = outerRadius * 0.75;
    const color = d3.scaleOrdinal<string, string>(d3.schemeObservable10);
    const arc = d3.arc<ArcDatum>().innerRadius(innerRadius).outerRadius(outerRadius);
    const pie = d3.pie<PieUpdateRow>().sort(null).value((d) => d[data.keys[0]]);

    const path = svg
      .selectAll<TweenedPath, ArcDatum>('path')
      .data(pie(data.rows))
      .join('path')
      .attr('fill', (_d, i) => color(String(i)))
      .attr('d', arc)
      .each(function (d) {
        (this as TweenedPath)._current = d; // store the initial angles
      });

    let step = 0;
    const timer = d3.interval(() => {
      step += 1;
      pie.value((d) => d[data.keys[step % data.keys.length]]); // change the value function

      path
        .data(pie(data.rows)) // compute the new angles
        .transition()
        .duration(DURATION)
        .attrTween('d', function (d) {
          // Interpolate from the stored angles to the new ones, updating
          // _current in place so an interrupted tween resumes cleanly.
          const node = this as TweenedPath;
          const interpolate = d3.interpolate(node._current ?? d, d);
          node._current = interpolate(0);
          return (t) => arc(interpolate(t)) ?? '';
        });
    }, INTERVAL);

    return () => {
      timer.stop();
      path.interrupt();
      svg.selectAll('*').remove();
    };
  }, [data, width, height]);

  if (width === 0) return null;

  return (
    <svg
      ref={ref}
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Donut chart transitioning slice angles between apples and oranges"
    />
  );
}
